  1→<script setup lang="ts">
  2→import { ref, computed, onMounted } from 'vue'
  3→import { getToken, getUserRoles } from '../auth'
  4→import { useRouter } from 'vue-router'
  5→
  6→const router = useRouter()
  7→const roles = getUserRoles()
  8→
  9→// Redirect students
 10→if (roles.includes('student') && !roles.includes('teacher') && !roles.includes('admin')) {
 11→  router.replace('/')
 12→}
 13→
 14→interface Option {
 15→  id: string
 16→  name: string
 17→}
 18→
 19→interface FileItem {
 20→  id: string
 21→  subjectId: string
 22→  groupId: string
 23→  fileName: string
 24→  fileSize: number
 25→  uploadedAt: string
 26→}
 27→
 28→const groups = ref<Option[]>([])
 29→const subjects = ref<Option[]>([])
 30→const files = ref<FileItem[]>([])
 31→
 32→const selectedGroup = ref('')
 33→const selectedSubject = ref('')
 34→const selectedFile = ref<File | null>(null)
 35→
 36→const MAX_FILE_SIZE_MB = 50
 37→const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024
 38→
 39→const fileInputRef = ref<HTMLInputElement | null>(null)
 40→const loading = ref(true)
 41→const uploading = ref(false)
 42→const error = ref<string | null>(null)
 43→const successMsg = ref<string | null>(null)
 44→
 45→const authHeaders = computed(() => ({
 46→  Authorization: `Bearer ${getToken()}`,
 47→}))
 48→
 49→function formatSize(bytes: number): string {
 50→  if (bytes < 1024) return `${bytes} Б`
 51→  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} КБ`
 52→  return `${(bytes / (1024 * 1024)).toFixed(1)} МБ`
 53→}
 54→
 55→function formatDate(iso: string): string {
 56→  return new Date(iso).toLocaleString('ru-RU')
 57→}
 58→
 59→function groupName(id: string): string {
 60→  return groups.value.find((g) => g.id === id)?.name ?? id
 61→}
 62→
 63→function subjectName(id: string): string {
 64→  return subjects.value.find((s) => s.id === id)?.name ?? id
 65→}
 66→
 67→async function loadData() {
 68→  loading.value = true
 69→  error.value = null
 70→  try {
 71→    const [groupsRes, subjectsRes, filesRes] = await Promise.all([
 72→      fetch('/api/teacher/groups', { headers: authHeaders.value }),
 73→      fetch('/api/teacher/subjects', { headers: authHeaders.value }),
 74→      fetch('/api/control-work', { headers: authHeaders.value }),
 75→    ])
 76→    if (!groupsRes.ok || !subjectsRes.ok || !filesRes.ok)
 77→      throw new Error('Ошибка загрузки данных')
 78→
 79→    groups.value = await groupsRes.json()
 80→    subjects.value = await subjectsRes.json()
 81→    files.value = await filesRes.json()
 82→  } catch (e) {
 83→    error.value = e instanceof Error ? e.message : 'Неизвестная ошибка'
 84→  } finally {
 85→    loading.value = false
 86→  }
 87→}
 88→
 89→function onFileChange(event: Event) {
 90→  const input = event.target as HTMLInputElement
 91→  const file = input.files?.[0] ?? null
 92→  error.value = null
 93→
 94→  if (file && file.size > MAX_FILE_SIZE_BYTES) {
 95→    error.value = `Файл слишком большой (${formatSize(file.size)}). Максимум ${MAX_FILE_SIZE_MB} МБ`
 96→    input.value = ''
 97→    selectedFile.value = null
 98→    return
 99→  }
100→
101→  selectedFile.value = file
102→}
103→
104→function resetForm() {
105→  selectedGroup.value = ''
106→  selectedSubject.value = ''
107→  selectedFile.value = null
108→  if (fileInputRef.value) fileInputRef.value.value = ''
109→}
110→
111→async function upload() {
112→  if (!selectedGroup.value || !selectedSubject.value || !selectedFile.value) return
113→
114→  uploading.value = true
115→  error.value = null
116→  successMsg.value = null
117→
118→  const formData = new FormData()
119→  formData.append('groupId', selectedGroup.value)
120→  formData.append('subjectId', selectedSubject.value)
121→  formData.append('file', selectedFile.value)
122→
123→  try {
124→    const res = await fetch('/api/control-work/upload', {
125→      method: 'POST',
126→      headers: authHeaders.value,
127→      body: formData,
128→    })
129→    if (!res.ok) {
130→      const body = await res.json().catch(() => null)
131→      throw new Error(body?.error ?? `HTTP ${res.status}`)
132→    }
133→    successMsg.value = 'Файл загружен'
134→    resetForm()
135→
136→    // Reload file list
137→    const filesRes = await fetch('/api/control-work', { headers: authHeaders.value })
138→    if (filesRes.ok) files.value = await filesRes.json()
139→  } catch (e) {
140→    error.value = e instanceof Error ? e.message : 'Ошибка загрузки'
141→  } finally {
142→    uploading.value = false
143→  }
144→}
145→
146→async function deleteFile(id: string) {
147→  if (!confirm('Удалить этот файл?')) return
148→
149→  try {
150→    const res = await fetch(`/api/control-work/${id}`, {
151→      method: 'DELETE',
152→      headers: authHeaders.value,
153→    })
154→    if (!res.ok) throw new Error(`HTTP ${res.status}`)
155→    files.value = files.value.filter((f) => f.id !== id)
156→  } catch (e) {
157→    error.value = e instanceof Error ? e.message : 'Ошибка удаления'
158→  }
159→}
160→
161→const filteredFiles = computed(() => {
162→  return files.value.filter((f) => {
163→    if (selectedGroup.value && f.groupId !== selectedGroup.value) return false
164→    if (selectedSubject.value && f.subjectId !== selectedSubject.value) return false
165→    return true
166→  })
167→})
168→
169→const canUpload = computed(
170→  () => selectedGroup.value && selectedSubject.value && selectedFile.value && !uploading.value,
171→)
172→
173→onMounted(loadData)
174→</script>
